x['review_notes']=[{'type':'source_collation','pages':list(range(549,557)),'note':'Первый фактический проход: все8 страниц549–556 прочитаны по рендерам1800px;548 и557 просмотрены исключительно для контекста и границы. Все8 изображений повторно просмотрены при обратной сверке. Сноски издателя/маркеры, орнаменты и титул указателей557 исключены. Само авторское обсуждение цитат и атрибуций полностью сохранено.'},{'type':'semantic_back_comparison','pages':list(range(549,557)),'note':'Второй фактический проход: AR/RU сопоставлены со всеми повторно просмотренными изображениями.549 сохранены оба возражения и различение атрибута Аллаха от пути раба;550–551 критикуемые монистические положения не выданы за мнение автора;551–553 сохранены оба благожелательных толкования и оговорки о разных значениях одной фразы, а также важнейшее различие стирания из сердца и уничтожения в бытии.552 сохранено различие отмены представления о собственности и отрицания самой ссуды.554–556 полностью переданы заключительная молитва, обращение к читателю, признание человеческой ошибочности и наставление о знании/справедливости.3 полных поэтических строки550/555 переданы без пропусков.'},{'type':'russian_only_reading','pages':list(range(549,557)),'note':'Третий фактический проход: весьRU прочитан отдельно. Заменён грамматически незавершённый зачин «Хотя эти3...» на «Впрочем...». В37:159–160 исключение передано в соответствии с немедленным авторским объяснением как исключение истинного описания избранных рабов. Все5 коранических фрагментов проверены на буквальное тождествоAR вRU; финальный42:15 полностью замкнут. Хеши, source_ids, последовательностьID и внутренние стыки проверены.'},{'type':'print_question','pages':[551,552,553,555],'note':'551 сохранено печатное «يمحو», не заменено вариантом «يمحق» из сноски.552 сохранено печатное «والمعير أبطل ظن المستعير من العارية» и «وإنما ضاق به الوزن», несмотря на замечания современных сносок; смысл передан по контексту,AR не исправлен догадкой.553 сохранено «التوحيد الحق», не вариант «والحق».555 сохранено «لم يأل جهد الإصابة», не ошибочный вариант «لم يأت». Цитируемые поэтические атрибуции550 переданы как атрибуции самого автора, без импорта издательского обсуждения.'},{'type':'uncertainty','pages':[551,554,555],'note':'Не проведена независимая человеческая/богословская проверка.551 «شهود الأزلية والحكم» передано «созерцание предвечности и установления», что требует терминологической редакции. В молитве554 «غير مكفي» принято в смысле отсутствия у Господа нужды в обеспечении; известны иные толкования этой формулы, нужен отдельный редакторский разбор,AR сохранён. Хадис555 «لا يؤمن أحدكم...» переведён как процитированный автором; достоверность его иснада отдельно не оценивалась, издательская сноска не импортирована.'}]
lookup={s['id']:s['ar'] for pg in x['pages'] for s in pg['paragraphs']};used=[]
